<script setup>
import {ref,nextTick} from 'vue';import PageHeader from '../../components/common/PageHeader.vue';import {suggestions} from '../../data/assistant.js';import {sendMessage} from '../../api/assistant.js';import {createConversation,appendUserMessage} from '../../utils/conversation.js'
const messages=ref(createConversation()),input=ref(''),sending=ref(false),list=ref();async function send(text=input.value){const value=text.trim();if(!value)return;messages.value=appendUserMessage(messages.value,value);input.value='';sending.value=true;await nextTick();list.value?.scrollTo({top:list.value.scrollHeight,behavior:'smooth'});const response=await sendMessage(value);messages.value.push({role:'assistant',text:response.data.message});sending.value=false;await nextTick();list.value?.scrollTo({top:list.value.scrollHeight,behavior:'smooth'})}function clear(){messages.value=createConversation()}
</script>
<template><div class="page-shell"><div class="container assistant-page"><PageHeader title="AI 定制助手" description="快速梳理空间、材料与预算问题，正式方案仍由设计师确认。" :breadcrumbs="['首页','AI 定制助手']"><el-button text @click="clear">清空对话</el-button></PageHeader><div class="chat-shell"><aside><h2>常见问题</h2><button v-for="x in suggestions" :key="x" @click="send(x)">{{x}}</button><div class="assistant-note"><b>使用说明</b><p>当前为静态演示回复，不会上传个人信息或调用真实大模型。</p></div></aside><main><div ref="list" class="message-list"><div v-for="(m,i) in messages" :key="i" :class="['message',m.role]"><span>{{m.role==='assistant'?'木序':'您'}}</span><p>{{m.text}}</p></div><div v-if="sending" class="message assistant"><span>木序</span><p>正在整理建议…</p></div></div><div class="composer"><el-input v-model="input" type="textarea" :rows="2" resize="none" placeholder="描述您的空间需求…" @keydown.enter.exact.prevent="send()"/><el-button type="primary" :loading="sending" @click="send()">发送</el-button></div></main></div></div></div></template>
<style scoped>.assistant-page{max-width:1050px}.chat-shell{height:650px;display:grid;grid-template-columns:250px 1fr;background:#fff;border:1px solid var(--c-border)}.chat-shell>aside{padding:22px;border-right:1px solid var(--c-border)}.chat-shell aside h2{font:500 18px var(--font-display)}.chat-shell aside button{display:block;width:100%;padding:10px 0;text-align:left;background:none;border:0;border-bottom:1px solid var(--c-soft);color:var(--c-muted);cursor:pointer}.chat-shell aside button:hover{color:var(--c-primary)}.assistant-note{margin-top:30px;padding-top:18px;border-top:1px solid var(--c-border)}.assistant-note p{color:var(--c-muted);font-size:12px}.chat-shell>main{min-width:0;display:grid;grid-template-rows:1fr auto}.message-list{padding:26px;overflow:auto}.message{display:flex;gap:12px;max-width:78%;margin-bottom:22px}.message>span{flex:0 0 34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--c-deep);color:#fff;font:13px var(--font-display)}.message p{margin:0;padding:10px 14px;background:var(--c-bg);border-radius:2px;white-space:pre-wrap}.message.user{margin-left:auto;flex-direction:row-reverse}.message.user>span{background:var(--c-primary)}.message.user p{background:#eee4dc}.composer{display:flex;gap:12px;padding:18px;border-top:1px solid var(--c-border)}.composer .el-button{height:54px}@media(max-width:700px){.chat-shell{grid-template-columns:1fr;height:70vh}.chat-shell>aside{display:none}.message{max-width:92%}}</style>
